import pandas as pd, numpy as np
from itertools import combinations
e=pd.read_csv('data/songs_echo_4.csv')
cols=['danceability','energy','speechiness','liveness','loudness','acousticness','valence','instrumentalness']
def report(name, fn):
 rows=[]
 for cut,d in e.groupby('cut'):
  X=d[cols].values.astype(float)
  rows.append((cut, round(fn(X),4)))
 print(name, rows)
# cosine distance
def cos(X):
 Xn=X/np.linalg.norm(X,axis=1,keepdims=True)
 S=Xn@Xn.T
 np.fill_diagonal(S,np.nan)
 return np.nanmean(1-S)
report('cosine',cos)
# correlation distance
def corr(X):
 C=np.corrcoef(X)
 return np.nanmean(1-C)
report('corr',corr)
# normalized by sd but weights
for divisor in [2,5,10]:
 def f(X):
  X2=X.copy(); X2[:,4]=X2[:,4]/divisor
  return np.mean([np.linalg.norm(X2[i]-X2[j]) for i,j in combinations(range(len(X2)),2)])
 report('raw loud/%d'%divisor,f)
"

